$ErrorActionPreference = "Stop"
$ExpectedHead = "47dcd73"
$ExpectedBranch = "main"
$Repo = (Get-Location).Path

if ((git branch --show-current).Trim() -ne $ExpectedBranch) { throw "Run this script from the main branch." }
$Head = (git rev-parse --short HEAD).Trim()
if ($Head -ne $ExpectedHead) { throw "Expected HEAD $ExpectedHead but found $Head. Pull/inspect before applying this batch." }
if (-not (Test-Path ".\mvnw.cmd")) { throw "Maven wrapper not found. Run from the LYAPUNOV repository root." }

git diff --quiet
if ($LASTEXITCODE -ne 0) { throw "Tracked working-tree changes exist. Commit or stash them before applying this batch." }
git diff --cached --quiet
if ($LASTEXITCODE -ne 0) { throw "Staged changes exist. Commit or unstage them before applying this batch." }

$Payload = @{}
$Payload.Add('src/main/java/com/lyapunov/health/HealthStatus.java', 'cGFja2FnZSBjb20ubHlhcHVub3YuaGVhbHRoOwoKcHVibGljIGVudW0gSGVhbHRoU3RhdHVzIHsKICAgIEhFQUxUSFksCiAgICBERUdSQURFRCwKICAgIFVOSEVBTFRIWQp9Cg==')
$Payload.Add('src/main/java/com/lyapunov/health/HealthCheckResult.java', '')
$Payload.Add('src/main/java/com/lyapunov/health/HealthCheckReport.java', '')
$Payload.Add('src/main/java/com/lyapunov/health/HealthProbe.java', 'cGFja2FnZSBjb20ubHlhcHVub3YuaGVhbHRoOwoKQEZ1bmN0aW9uYWxJbnRlcmZhY2UKcHVibGljIGludGVyZmFjZSBIZWFsdGhQcm9iZSB7CiAgICBIZWFsdGhDaGVja1Jlc3VsdCBjaGVjaygpOwp9Cg==')
$Payload.Add('src/main/java/com/lyapunov/health/HealthCheckService.java', '')
$Payload.Add('src/main/java/com/lyapunov/cli/HealthCheckCli.java', '')
$Payload.Add('src/test/java/com/lyapunov/health/HealthCheckReportTest.java', '')
$Payload.Add('src/test/java/com/lyapunov/health/HealthCheckServiceTest.java', '')
$Payload.Add('docs/HEALTH_CHECKS_AND_READINESS.md', '')

foreach ($relativePath in $Payload.Keys) {
    $fullPath = Join-Path $Repo $relativePath
    $parent = Split-Path -Parent $fullPath
    if (-not (Test-Path $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
    $bytes = [Convert]::FromBase64String($Payload[$relativePath])
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "Wrote $relativePath"
}

Write-Host "`nRunning Maven clean verify..."
& .\mvnw.cmd -B -ntp clean verify
if ($LASTEXITCODE -ne 0) { throw "Maven verification failed. No files were staged or committed." }

$Paths = @(
    'src\main\java\com\lyapunov\health\HealthStatus.java'
    'src\main\java\com\lyapunov\health\HealthCheckResult.java'
    'src\main\java\com\lyapunov\health\HealthCheckReport.java'
    'src\main\java\com\lyapunov\health\HealthProbe.java'
    'src\main\java\com\lyapunov\health\HealthCheckService.java'
    'src\main\java\com\lyapunov\cli\HealthCheckCli.java'
    'src\test\java\com\lyapunov\health\HealthCheckReportTest.java'
    'src\test\java\com\lyapunov\health\HealthCheckServiceTest.java'
    'docs\HEALTH_CHECKS_AND_READINESS.md'
)

git add -- $Paths
if ($LASTEXITCODE -ne 0) { throw "git add failed." }

git diff --cached --check
if ($LASTEXITCODE -ne 0) { throw "Staged diff whitespace check failed." }

git commit -m "feat: add dependency health and readiness probes"
if ($LASTEXITCODE -ne 0) { throw "Commit failed. Review the staged changes." }

git push origin main
if ($LASTEXITCODE -ne 0) { throw "Push failed. The local commit exists; inspect remote state before retrying." }

Write-Host "`nBATCH 09 COMPLETE: verified, committed, and pushed."
git log -1 --oneline --decorate
git status -sb
